mapper.select:
SELECT id, event_key, route_id, driver_id, device_code, captured_at, received_at,
       longitude, latitude, geom_crs, accuracy_meters, speed_kph, reported_by
FROM delivery_gps_event
WHERE route_id = #{routeId}

    AND captured_at >= #{from}


    AND captured_at <= #{to}

ORDER BY captured_at ASC, id ASC
LIMIT #{limit}
